-- The QUICK-PENTA code key (Code keys -> Parting -> QUICK-PENTA), from the
-- ISCAR e-catalog's QUICK-PENTA families (PENTA 24 ...SL inserts, PCHR/L-QC,
-- PCHRS-QC, PCADR/L-QC tools); kept if one exists. The PENTACUT key leaves
-- its QUICK-PENTA (SL) section to it.
INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.quickpenta', $ck${"title": "QUICK-PENTA code key – inserts and tools", "subtitle": "PENTA 24 inserts with 5 cutting edges and safety lock clamping (SL) for quick cutting edge indexing, and their QC holders and adapters", "example": "PENTA 24N200C020SL", "decoder": "quick-penta", "sections": [{"key": "i-family", "title": "Insert – family", "sample": "PENTA", "rows": [{"code": "PENTA", "meaning": "Pentagonal insert with 5 cutting edges"}]}, {"key": "i-size", "title": "Insert – size", "sample": "24", "rows": [{"code": "24", "meaning": "PENTA 24"}]}, {"key": "i-hand", "title": "Insert – hand", "sample": "N", "rows": [{"code": "N", "meaning": "Neutral"}, {"code": "R", "meaning": "Right-hand (lead angle)"}, {"code": "L", "meaning": "Left-hand (lead angle)"}]}, {"key": "i-width", "title": "Insert – cutting width", "sample": "200", "rows": [{"code": "###", "meaning": "Cutting width x100 (e.g. 200 = 2.00 mm)"}]}, {"key": "i-chip", "title": "Chipformer", "sample": "C", "rows": [{"code": "C", "meaning": "Parting of bars, hard materials and tough applications"}, {"code": "J", "meaning": "Parting and grooving with a positive rake angle (also tubes, thin-walled parts)"}, {"code": "NF", "meaning": "Precision grooving next to high shoulders (RS)"}, {"code": "B", "meaning": "Soft and ductile materials such as 100Cr6 (bearing steel)"}]}, {"key": "i-radius", "title": "Insert – corner radius", "sample": "020", "rows": [{"code": "###", "meaning": "Corner radius x100 (e.g. 020 = 0.20 mm; 000 = sharp; 079 on 1.57 = full radius)"}, {"code": "##", "meaning": "Corner radius x10 (e.g. NF01 = 0.1 mm, NF02 = 0.2 mm)"}]}, {"key": "i-lead", "title": "Insert – lead angle", "rows": [{"code": "##D", "meaning": "Lead angle in degrees (06D = 6°, 15D = 15°) to minimize the burr"}]}, {"key": "i-side", "title": "Insert – side version", "rows": [{"code": "RS", "meaning": "Right side version, next to high shoulders"}]}, {"key": "i-lock", "title": "Insert – safety lock", "sample": "SL", "rows": [{"code": "SL", "meaning": "Safety lock clamping for quick cutting edge indexing (QC tools)"}]}, {"key": "t-family", "title": "Tool – family", "rows": [{"code": "PCH", "meaning": "Grooving, parting and recessing tools (PCHR / PCHL; PCHRS next to high shoulders)"}, {"code": "PCAD", "meaning": "QUICK-PENTA adapters with high-pressure coolant holes (PCADR / PCADL)"}]}, {"key": "t-hand", "title": "Tool – hand", "rows": [{"code": "R", "meaning": "Right-hand"}, {"code": "L", "meaning": "Left-hand"}]}, {"key": "t-height", "title": "Tool – shank", "rows": [{"code": "##", "meaning": "Shank size in mm (12, 16, 20, 25)"}]}, {"key": "t-penta", "title": "Tool – PENTA size seat", "rows": [{"code": "24", "meaning": "For PENTA 24 inserts"}]}, {"key": "t-suffix", "title": "Tool – suffixes", "rows": [{"code": "S", "meaning": "Next to high shoulders (PCHRS)"}, {"code": "JHP", "meaning": "Channels for high-pressure coolant"}, {"code": "MC", "meaning": "Bottom inlets for the high-pressure coolant"}, {"code": "QC", "meaning": "Quick change – safety lock clamping for QUICK-PENTA SL inserts"}]}]}$ck$)
ON CONFLICT ("key") DO NOTHING;

UPDATE "AppSetting"
SET "value" = jsonb_set("value"::jsonb, '{sections}', (
  SELECT COALESCE(jsonb_agg(s), '[]'::jsonb) FROM jsonb_array_elements("value"::jsonb -> 'sections') s WHERE s ->> 'key' <> 'i-lock'
))::text
WHERE "key" = 'codekey.penta';

UPDATE "AppSetting" SET "value" = jsonb_set("value"::jsonb, '{subtitle}', '"Inserts with 5 cutting edges: PENTA 17 / 24 / 34, PENTA 34F face grooving, PENTAS 27 blanks, PENTA D (PENTA IQ GRIP) and PMN D (FLASHPENTA), and their tools"')::text
WHERE "key" = 'codekey.penta' AND "value"::jsonb ->> 'subtitle' = 'Inserts with 5 cutting edges: PENTA 17 / 24 / 34 (PENTACUT, QUICK-PENTA SL), PENTA 34F face grooving, PENTAS 27 blanks, PENTA D (PENTA IQ GRIP) and PMN D (FLASHPENTA), and their tools';
